// 1. 经典观察者模式基础结构
public interface Subject {
    void registerObserver(Observer observer);
    void removeObserver(Observer observer);
    void notifyObservers();
}
public interface Observer {
    void update(String message);
}
public class ConcreteSubject implements Subject {
    private final List<Observer> observers = new ArrayList<>();
    private String state;

    @Override
    public void registerObserver(Observer observer) {
        observers.add(observer);
    }

    @Override
    public void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    @Override
    public void notifyObservers() {
        for (Observer observer : observers) {  // 同步遍历，异常会中断
            observer.update(state);
        }
    }

    public void setState(String state) {
        this.state = state;
        notifyObservers(); // 状态变更入口内联通知
    }
}

// 2. Spring 事件：定义 + 发布 + 监听
public class OrderCreatedEvent {
    private final String orderId;
    private final BigDecimal amount;
    public OrderCreatedEvent(String orderId, BigDecimal amount) {
        this.orderId = orderId;
        this.amount = amount;
    }
    // getter 省略
}

@Service
public class OrderService {
    @Autowired
    private ApplicationEventPublisher publisher;

    @Transactional
    public void createOrder(String orderId, BigDecimal amount) {
        // ... 保存订单
        publisher.publishEvent(new OrderCreatedEvent(orderId, amount));
        // publishEvent 内部同步执行所有匹配监听器，共享本事务
    }
}

// 3. 同步监听（默认，在发布方线程/事务里）
@Component
public class AuditListener {
    @EventListener(condition = "#event.amount.compareTo(T(java.math.BigDecimal).valueOf(1000)) > 0")
    public void auditLargeOrder(OrderCreatedEvent event) {
        // SpEL 过滤：只处理金额 > 1000 的订单
        log.info("大额订单审计: {}", event.getOrderId());
    }
}

// 4. 事务提交后才执行（避免回滚后副作用已落地）
@Component
public class NotificationListener {
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void sendNotification(OrderCreatedEvent event) {
        // 只在事务成功提交后才发短信/写缓存
        smsService.send(event.getOrderId());
    }
}

// 5. 异步监听（独立线程，不拖发布方）
@Component
public class PointsListener {
    @Async("pointsExecutor")  // 需要 @EnableAsync + 自定义线程池
    @EventListener
    public void addPoints(OrderCreatedEvent event) {
        pointsService.add(event.getOrderId(), event.getAmount());
    }
}
